<?php
require_once __DIR__.'/includes/auth.php';require_manager();
$month=$_GET['month']??date('Y-m');if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=date('Y-m');
$s=$pdo->prepare("SELECT COUNT(*) staff_count,COALESCE(SUM(overtime_hours),0) ot_hours,COALESCE(SUM(total_allowance),0) allowance,COALESCE(SUM(total_deduction),0) deduction,COALESCE(SUM(gross_salary),0) gross,COALESCE(SUM(net_salary),0) net FROM payroll WHERE salary_month=?");$s->execute([$month]);$sum=$s->fetch();
$s=$pdo->prepare("SELECT p.*,e.employee_code,e.full_name,e.position FROM payroll p JOIN employees e ON e.id=p.employee_id WHERE p.salary_month=? ORDER BY e.full_name");$s->execute([$month]);$rows=$s->fetchAll();
require __DIR__.'/includes/layout.php';page_start('Laporan Gaji','reports');?>
<div class="page-intro d-flex justify-content-between flex-wrap gap-3"><div><h2>Laporan gaji</h2><p>Ringkasan payroll mengikut bulan yang dipilih.</p></div><form class="d-flex gap-2" method="get"><input class="form-control" type="month" name="month" value="<?=h($month)?>"><button class="btn btn-primary">Tapis</button></form></div>
<div class="row g-3 mb-4"><?php foreach([['Pekerja diproses',number_format((int)$sum['staff_count'])],['Gaji kasar','RM '.number_format((float)$sum['gross'],2)],['Jumlah potongan','RM '.number_format((float)$sum['deduction'],2)],['Gaji bersih','RM '.number_format((float)$sum['net'],2)]] as $x):?><div class="col-6 col-xl-3"><div class="metric-card"><div class="metric-label"><?=h($x[0])?></div><div class="metric-value fs-4"><?=h($x[1])?></div></div></div><?php endforeach;?></div>
<div class="panel-card"><div class="panel-heading"><h3>Payroll <?=h($month)?></h3><button class="btn btn-outline-secondary btn-sm no-print" onclick="window.print()">Cetak laporan</button></div><div class="table-responsive"><table class="table"><thead><tr><th>Kod</th><th>Nama</th><th>Gaji asas</th><th>OT</th><th>Elaun</th><th>Potongan</th><th>Gaji bersih</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['employee_code'])?></td><td><?=h($r['full_name'])?></td><td><?=number_format((float)$r['basic_salary'],2)?></td><td><?=number_format((float)$r['overtime_pay'],2)?></td><td><?=number_format((float)$r['total_allowance'],2)?></td><td><?=number_format((float)$r['total_deduction'],2)?></td><td><b><?=number_format((float)$r['net_salary'],2)?></b></td><td><a href="payslip.php?id=<?=(int)$r['id']?>" class="btn btn-sm btn-outline-primary">Slip</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="text-center muted">Tiada rekod payroll untuk bulan ini.</td></tr><?php endif;?></tbody></table></div></div>
<?php page_end();?>